package com.steadyme.app.ui;import android.os.Bundle;import android.view.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.LinearLayoutManager;import com.google.android.material.snackbar.Snackbar;import com.google.firebase.firestore.ListenerRegistration;import com.steadyme.app.data.FirebaseRepository;import com.steadyme.app.databinding.FragmentHistoryBinding;
public class HistoryFragment extends Fragment{private FragmentHistoryBinding binding;private ListenerRegistration registration;private final MoodLogAdapter adapter=new MoodLogAdapter();@Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){binding=FragmentHistoryBinding.inflate(i,c,false);return binding.getRoot();}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){binding.rvMoodHistory.setLayoutManager(new LinearLayoutManager(requireContext()));binding.rvMoodHistory.setAdapter(adapter);registration=new FirebaseRepository().observeMoodLogs(new FirebaseRepository.LogsCallback(){public void onLoaded(java.util.List<com.steadyme.app.model.MoodLog> l){adapter.submit(l);binding.tvEmptyHistory.setVisibility(l.isEmpty()?View.VISIBLE:View.GONE);}public void onError(Exception e){Snackbar.make(binding.getRoot(),e.getMessage(),Snackbar.LENGTH_LONG).show();}});}@Override public void onDestroyView(){if(registration!=null)registration.remove();binding=null;super.onDestroyView();}}
